import pathlib,stat,json
root=pathlib.Path('/home/appontrack/public_html/ayo')
files=('api.php','index.php','app.js','style.css','audio-worklet.js','ontrack.json')
if not root.is_dir():raise RuntimeError('AYO root missing')
before={}
for name in files:
 p=root/name
 if not p.is_file() or p.is_symlink():raise RuntimeError('Unexpected AYO file '+name)
 before[name]=oct(stat.S_IMODE(p.stat().st_mode))
 p.chmod(0o644)
print(json.dumps({'scope':str(root),'before':before,'after':{n:oct(stat.S_IMODE((root/n).stat().st_mode)) for n in files}}))
